    ["[missy|motel clerk] rented [rooms|302 304 307]. [never checked out|keys still out]"] = "[missy|recepcionista do motel] alugou [quartos|302 304 307]. [nunca saíram|chaves ainda fora]",
    ["[rev lois|march ridge] making [list|pantry list]. missing growing. food"] = "[rev lois|march ridge] fazendo [lista|lista da despensa]. desaparecidos aumentando. comida",
    ["[tony|pizza] cant get [through|to hospital]. roadblock at river"] = "[tony|pizza] não consegue [passar|chegar ao hospital]. bloqueio no rio",
    ["[shirley|grandma] texts [every day|every morning]. [neighbor|mrs davis] answered today"] = "[shirley|vovó] manda mensagem [todo dia|toda manhã]. [vizinha|sra davis] respondeu hoje",
    ["[doug|mailman] marked [houses|route] with no answer. 7 so far"] = "[doug|carteiro] marcou [casas|rota] sem resposta. 7 até agora",
    ["Day [3|4|5]. [no TV|no phone|no power]. waiting for [{partner}|{mom}|{dad}]"] = "Dia [3|4|5]. [sem TV|sem telefone|sem luz]. esperando [{partner}|{mom}|{dad}]",
    ["if i dont [text|call] by [6|dark|noon] [dont come|stay put|lock door]"] = "se eu não [mandar mensagem|ligar] até [6|escurecer|meio-dia] [não venha|fique aí|tranque a porta]",
    ["[{partner}|{friend}] has the [keys|gun|truck]. meet at {jobPlace}"] = "[{partner}|{friend}] está com [as chaves|a arma|o caminhão]. encontro em {jobPlace}",
    ["heard [shots|screams|trucks] on [Main|31W|river road] at 2am. dog didnt wake"] = "ouvi [tiros|gritos|caminhões] na [Main|31W|estrada do rio] às 2 da manhã. o cachorro nem acordou",
    ["[{mom}|{dad}] said [come home|stay there|pray]. cant leave"] = "[{mom}|{dad}] disse [volte pra casa|fique aí|reze]. não posso sair",
    ["It's Mom. Your father's phone goes straight to voicemail. And you're not answering. [Honey|{first}], please. Just pick up. [I'm|We're] scared."] = "É a mamãe. O celular do seu pai cai direto na caixa postal. E você não está atendendo. [Querido|{first}], por favor. Só atenda. [Estou|Estamos] com medo.",
    ["[{first}|Hey]. The kids are asking for you. [I|We] told you're working. Call me. Please."] = "[{first}|Ei]. As crianças estão perguntando por você. [Eu disse|Nós dissemos] que você está trabalhando. Me ligue. Por favor.",
    ["It's me. Your father checked the generator [this morning|again at noon] and it's holding. Call me back when you can"] = "Sou eu. Seu pai verificou o gerador [esta manhã|de novo ao meio-dia] e está aguentando. Me ligue de volta quando puder",
    ["Honey, I tried the house phone again. Nothing. Your [sister|brother] went to the IGA for water. Call me back, hon"] = "Querido, tentei o telefone de casa de novo. Nada. Seu [irmão|irmã] foi ao IGA buscar água. Me ligue de volta, meu bem",
    ["It's me. Grandma's fan quit [around three|after lunch]. We gave her the one from the hall closet. Call me when you get this"] = "Sou eu. O ventilador da vovó parou [por volta das três|depois do almoço]. Demos a ela o do armário do corredor. Me ligue quando receber isto",
    ["It's your father. The truck's still making that knock. I'll look at it Sunday. Call me back"] = "É seu pai. A caminhonete ainda está com aquele barulho. Vou dar uma olhada no domingo. Me ligue de volta",
    ["Your mother's worried. She won't say it but I can tell. Call home. Let us know you're all right"] = "Sua mãe está preocupada. Ela não diz, mas eu percebo. Ligue para casa. Avise que você está bem",
    ["It's Dad. The cooler's still in the bed of the truck from the Fourth. Bring it back when you can"] = "É o papai. A caixa térmica ainda está na caçamba da caminhonete desde o Quatro de Julho. Traga de volta quando puder",
    ["its me. moms making her [famous|awful] potato salad tomorrow. she said ask if youre coming. call me back"] = "sou eu. a mãe vai fazer a salada de batata [famosa|horrível] dela amanhã. pediu pra perguntar se vc vem. me liga de volta",
    ["hey its me. found dads old CB in the garage. mostly static but i heard voices by the river. call back"] = "oi sou eu. achei o velho PX do pai na garagem. quase só estática mas ouvi vozes perto do rio. liga de volta",
    ["its me. the lights went out at moms [around eight|just now]. generator kicked on. call me back please"] = "sou eu. a luz acabou na casa da mãe [por volta das oito|agora há pouco]. o gerador ligou. me liga de volta por favor",
    ["It's me. I kept the porch light on [like you asked|anyway]. The kids are asleep. Please call me back"] = "Sou eu. Deixei a luz da varanda acesa [como você pediu|mesmo assim]. As crianças estão dormindo. Por favor, me ligue de volta",
    ["It's me. The baby finally went down after the sirens stopped. I'm just sitting here with the phone. Call me"] = "Sou eu. O bebê finalmente dormiu depois que as sirenes pararam. Estou aqui sentada com o telefone. Me ligue",
    ["It's me. Your keys are in the bowl by the door. I didn't move them. Call me back. Please"] = "Sou eu. Suas chaves estão na tigela perto da porta. Não mexi nelas. Me ligue de volta. Por favor",
    ["Hey. It's me. The car's still in the drive with [half a tank|the gas light on]. Call me when you get this"] = "Oi. Sou eu. O carro ainda está na entrada com [meio tanque|a luz da gasolina acesa]. Me ligue quando receber isto",
    ["its me. the kroger on dixie got a truck in. water, cans, batteries. line's long. call me back"] = "sou eu. chegou um caminhão no kroger da dixie. água, enlatados, pilhas. a fila tá grande. me liga de volta",
    ["its me. heard popping by the [lumberyard|school] around midnight. probably nothing. call me back"] = "sou eu. ouvi estouros perto [da madeireira|da escola] por volta da meia-noite. provavelmente nada. me liga de volta",
    ["This is {work} at {jobPlace}. Your shift [tomorrow|Saturday] is covered. Call us back when you get this"] = "Aqui é {work} em {jobPlace}. Seu turno [amanhã|de sábado] está coberto. Ligue de volta quando receber isto",
    ["It's {work}. We're running short on the night crew. Call in when you can. We're holding your spot"] = "É {work}. Estamos com pouca gente no turno da noite. Ligue quando puder. Estamos segurando sua vaga",
    ["This is {work}. The chief wants a headcount. Call in when you get this"] = "Aqui é {work}. O chefe quer uma contagem do pessoal. Ligue quando receber isto",
    ["It's your mother. I put fresh sheets on your bed. The blue ones you like. Call me back, honey"] = "É sua mãe. Coloquei lençóis limpos na sua cama. Os azuis de que você gosta. Me ligue de volta, querido",
    ["hey its me. found your old baseball glove in the hall closet. thought youd want it. call me"] = "oi sou eu. achei sua velha luva de beisebol no armário do corredor. achei que você ia querer. me liga",
    ["It's me. I filled the tub and the big pots like you said. Just in case. Call me"] = "Sou eu. Enchi a banheira e as panelas grandes como você disse. Por precaução. Me ligue",
    ["It's me. The dog won't stop whining at the back door. It's been hours. Call me please"] = "Sou eu. O cachorro não para de chorar na porta dos fundos. Já faz horas. Me ligue, por favor",
    ["[Coffee|Coffee's] ready in the break room. [Fresh pot|Burnt again]"] = "[Café pronto|O café está pronto] na sala de descanso. [Coado agora|Queimado de novo]",
    ["Anyone seen my [clipboard|radio charger]? Left it by the [dispatch board|coffee maker]"] = "Alguém viu [minha prancheta|meu carregador de rádio]? Deixei perto [do quadro da central|da cafeteira]",
    ["[Trish|Dee] swapped with me for [tonight|tomorrow night]. [Thanks|Owe you one]"] = "[A Trish|A Dee] trocou comigo [hoje à noite|amanhã à noite]. [Obrigado|Te devo uma]",
    ["Road crew hit a water main on [31W|Main St]. [Expect delays|Detour by the plant]"] = "A equipe da obra rompeu uma adutora na [31W|Main St]. [Esperem atrasos|Desvio pela fábrica]",
    ["[Unit 4|Medic 2] back in service. [Cleaned up|Restocked] and ready"] = "[Unidade 4|Médico 2] de volta ao serviço. [Limpa|Reabastecida] e pronta",
    ["Shift change in [10|15]. [Relief's|The next crew's] pulling in now"] = "Troca de turno em [10|15]. [O reforço|A próxima equipe] está chegando agora",
    ["[Lunch|Dinner] run to [Spiffo's|the diner]. [Want anything|Grab me a burger]?"] = "Saída para [almoçar|jantar] [no Spiffo's|na lanchonete]. [Querem alguma coisa|Peguem um hambúrguer pra mim]?",
    ["AC's acting up in [dispatch|the squad room] again. [Maintenance|Facilities] says [Tuesday|next week]"] = "O ar-condicionado da [central|sala da equipe] está dando problema de novo. [A manutenção|A administração] diz [terça|semana que vem]",
    ["[Wade|Deputy Lusk] called out sick. [Flu|Something going around]. [Cover|Need someone] for his sector"] = "[O Wade|O policial Lusk] ligou avisando que está doente. [Gripe|Algo que está pegando]. [Cubram|Preciso de alguém para] o setor dele",
    ["New guy starts [Monday|Wednesday]. [Show him the ropes|Don't let him break anything]"] = "O novato começa [segunda|quarta]. [Mostrem como funciona|Não deixem ele quebrar nada]",
    ["[Carl|The foreman] wants the [night shift|weekend crew] on the furnace line. Overtime"] = "[O Carl|O capataz] quer [o turno da noite|a equipe do fim de semana] na linha do forno. Hora extra",
    ["Generator test at [0800|noon]. [Expect noise|Power flicker] for a minute"] = "Teste do gerador às [8h|meio-dia]. [Esperem barulho|Vai piscar a luz] por um minuto",
    ["[Tammy|Missy] at the [motel|Spiffo's] says business is slow. Lucky her"] = "[Tammy|Missy] do [motel|Spiffo's] diz que o movimento está fraco. Sortuda",
    ["County [fair|softball tournament] this weekend. [Sign up|Who's playing] at the [station|break room] board"] = "[Feira do condado|Torneio de softbol do condado] neste fim de semana. [Inscrições|Quem vai jogar] no quadro [do posto|da sala de descanso]",
    ["[Ray|The tower tech] was out at [KM-09|KM-12] all night. Site's up. Good work"] = "[Ray|O técnico da torre] ficou em [KM-09|KM-12] a noite toda. A estação voltou. Bom trabalho",
    ["[Dr. Sato|Ellen] sent a memo: [hydration breaks|watch for heat exhaustion] every hour. [Serious|Not optional]"] = "[Dra. Sato|Ellen] mandou um comunicado: [pausas para hidratação|atenção à exaustão pelo calor] a cada hora. [É sério|Não é opcional]",
    ["Pharmacy on [Dixie|Main] ran out of [IV bags|saline]. [Central supply|The hospital] sending a crate"] = "A farmácia da [Dixie|Main] ficou sem [bolsas de soro|soro fisiológico]. [O almoxarifado|O hospital] vai mandar uma caixa",
    ["[Lou|The captain] wants [incident reports|run sheets] done before shift end. No exceptions"] = "[Lou|O capitão] quer [os relatórios de ocorrência|as fichas de atendimento] prontos antes do fim do turno. Sem exceção",
    ["Kids' [soccer|baseball] game at the [school|field] Saturday. [Concession stand|Scoreboard] needs volunteers"] = "O jogo de [futebol|beisebol] da criançada é no sábado, no [colégio|campo]. [A barraquinha de lanches|O placar] precisa de voluntários",
    ["[Jimmy|The bartender] says [Twiggy's|the bar] closed Monday for repairs. Weird"] = "[Jimmy|O barman] disse que [o Twiggy's|o bar] fechou na segunda para reparos. Estranho",
    ["Mail's running [late|early] today. [Doug|The carrier] said bridge work on 31W"] = "O correio está [atrasado|adiantado] hoje. [Doug|O carteiro] disse que tem obra na ponte da 31W",
    ["[All circuits busy|Lines jammed] on the [landlines|radio]. [Cell's|Knox Mobile] still working tho"] = "[Todos os circuitos ocupados|Linhas congestionadas] nos [telefones fixos|rádios]. [O celular|O Knox Mobile] continua funcionando, mas",
    ["Heard [Louisville|the city] ER's [overflowing|on divert]. Dr. Sato hasn't gone home in two days"] = "Ouvi dizer que o pronto-socorro de [Louisville|da cidade] está [transbordando|desviando ambulâncias]. A Dra. Sato não vai pra casa faz dois dias",
    ["[Pastor Glen|The church] opened the [basement|fellowship hall] for anyone. Cots needed"] = "[O pastor Glen|A igreja] abriu [o porão|o salão comunitário] pra quem precisar. Faltam catres",
    ["[Coach Burris|Dale] cancelled [practice|weights] tomorrow. [First time|Never] seen him do that"] = "[O técnico Burris|Dale] cancelou [o treino|a musculação] amanhã. [Primeira vez que vejo|Nunca vi] ele fazer isso",
    ["National Guard at the [31W|county line] checkpoint. [Turning cars|Checking IDs]. [Nobody|Few] getting through"] = "Guarda Nacional no bloqueio [da 31W|da divisa do condado]. [Mandando carros voltarem|Checando identidades]. [Ninguém|Poucos] passando",
    ["[Lonnie|The trucker] stuck at the [roadblock|fence] with a full trailer. Since midnight"] = "[Lonnie|O caminhoneiro] preso [no bloqueio|na cerca] com a carreta cheia. Desde a meia-noite",
    ["[Trish|Dee] says [the hospital|ER] locked the ambulance bay. Walk-ins only"] = "[Trish|Dee] disse que [o hospital|o pronto-socorro] trancou a entrada das ambulâncias. Só quem chega a pé",
    ["Dispatch getting [calls|reports] of [people biting|fights] on Main. Send two units"] = "A central está recebendo [chamados|relatos] de [pessoas mordendo outras|brigas] na Main. Mandem duas viaturas",
    ["[Wade|Deputy Lusk] went to a [disturbance|call] on Main St 20 mins ago. No answer"] = "[Wade|Policial Lusk] foi a [um tumulto|uma ocorrência] na Main St 20 min atrás. Sem resposta",
    ["[Ray|Pruitt] headed to [KM-07|the Riverside site] on foot. Tower's down. Be careful"] = "[Ray|Pruitt] foi a pé pra [KM-07|a torre de Riverside]. A torre caiu. Cuidado",
    ["Landlines [dead|gone] in [Rosewood|Muldraugh|West Point]. Cell only thing working. Keep phones charged"] = "Telefones fixos [mortos|fora do ar] em [Rosewood|Muldraugh|West Point]. Só o celular está funcionando. Mantenham os celulares carregados",
    ["[Lyle|Fentress] at the [prison|Rosewood] says lockdown. No visits. Quiet"] = "[Lyle|Fentress] [da prisão|de Rosewood] diz que está em lockdown. Sem visitas. Silêncio",
    ["[Missy|The motel clerk] rented [every room|the last six] to families with cash. Nobody checked out"] = "[Missy|A recepcionista do motel] alugou [todos os quartos|os últimos seis] para famílias, em dinheiro. Ninguém deu saída",
    ["[Gus|Oberholtzer] at the [Brott farm|Irvington] says cattle been bellowing all night. Never heard that before"] = "[Gus|Oberholtzer] [da fazenda Brott|de Irvington] diz que o gado está berrando a noite toda. Nunca ouvi isso",
    ["[Tony|DeLuca] tried [three|four] runs to the hospital. Blocked at the checkpoint every time"] = "[Tony|DeLuca] tentou [três|quatro] viagens até o hospital. Barrado no bloqueio todas as vezes",
    ["[Grace|Pettit] at the [Country Club|West Maple] said the Fourth party ended early. People left fast"] = "[Grace|Pettit] [do Country Club|da West Maple] disse que a festa de 4 de Julho acabou cedo. O pessoal saiu correndo",
    ["[Earl|Pickett] on CB says [sky's|air's] wrong over Irvington. No birds"] = "[Earl|Pickett] no rádio PX diz que tem algo errado com [o céu|o ar] sobre Irvington. Nenhum pássaro",
    ["[Rev. Abney|Lois] at [March Ridge|the Methodist church] started a list of missing. Names growing"] = "[Rev. Abney|Lois] [de March Ridge|da igreja metodista] começou uma lista de desaparecidos. Os nomes só aumentam",
    ["[Shirley|Grandma Mattingly] didn't answer her [phone|door] today. Neighbor said she's fine. Checked twice"] = "[Shirley|Vovó Mattingly] não atendeu [o telefone|a porta] hoje. A vizinha disse que ela está bem. Conferi duas vezes",
    ["[Sgt. Bell|Marcus] texted [his wife|home]: can't say. At the checkpoint. Last message"] = "[Sgt. Bell|Marcus] mandou mensagem pra [a esposa|casa]: não posso falar. No bloqueio. Última mensagem",
    ["[Danny|Coyle] texted his [mom|mother]: pray for us. Private from Ohio. Stopped since yesterday"] = "[Danny|Coyle] mandou mensagem pra [mãe|mamãe]: rezem por nós. Soldado raso de Ohio. Parou ontem",
    ["If [anyone|you] gets [through|a signal] on the radio, relay dispatch we're holding. Don't leave {jobPlace}"] = "Se [alguém|você] conseguir [falar|sinal] no rádio, avise a central que estamos resistindo. Não saiam de {jobPlace}",
    ["[Last|Final] check: [water|coffee|ammo|batteries] in the locker. Enough. Ration it"] = "[Última|Derradeira] checagem: [água|café|munição|pilhas] no armário. É suficiente. Racionem",
    ["Dispatch log: Lusk 10-7 Main St 0200. No 10-8. Radio silent. Wade? You copy? {town}"] = "Registro da central: Lusk 10-7 Main St 0200. Sem 10-8. Rádio mudo. Wade? Câmbio? {town}",
}
